// Baselines are intentionally generated by the owner on their local machine.
// Run: flutter test test/plugins/view/plugin_controls_golden_test.dart --update-goldens
import 'package:dsh_app/ui/plugins/view/plugin_view.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'plugin_controls_fixtures.dart';
import 'support.dart';

void main() {
  setUpAll(loadTestFonts);
  for (final brightness in Brightness.values) {
    for (final fixture in ['inputs', 'structure']) {
      testWidgets('v2 controls $fixture ${brightness.name}', (tester) async {
        usePhoneView(tester);
        tester.view.physicalSize = Size(780, fixture == 'inputs' ? 5600 : 4000);
        await tester.pumpWidget(
          testApp(
            Scaffold(
              body: SingleChildScrollView(
                padding: const EdgeInsets.all(16),
                child: PluginFrame(
                  pluginName: 'Workbench',
                  child: PluginView(
                    view: fixture == 'inputs' ? inputFixture : structureFixture,
                    data: controlsData,
                    onAction: (_) async => true,
                  ),
                ),
              ),
            ),
            brightness: brightness,
          ),
        );
        await tester.pump();
        expect(tester.takeException(), isNull);
        await expectLater(
          find.byType(Scaffold),
          matchesGoldenFile('goldens/plugin_controls_${fixture}_${brightness.name}.png'),
        );
      });
    }
  }
  testWidgets('v2 narrow large text', (tester) async {
    usePhoneView(tester);
    tester.view.physicalSize = const Size(640, 2600);
    tester.platformDispatcher.textScaleFactorTestValue = 2;
    addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);
    await tester.pumpWidget(
      testApp(
        Scaffold(
          body: SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: PluginView(
              view: {
                'v': 2,
                'type': 'form',
                'submit': 'save',
                'children': [
                  {'type': 'textField', 'label': 'A descriptive field label', 'bind': 'data.name', 'required': true},
                  {
                    'type': 'segmented',
                    'label': 'Selection',
                    'bind': 'data.mode',
                    'options': ['Short', 'A longer choice that wraps'],
                  },
                ],
              },
              onAction: (_) async => true,
            ),
          ),
        ),
      ),
    );
    await tester.tap(find.byKey(const ValueKey('submit:view')));
    await tester.pumpAndSettle();
    expect(tester.takeException(), isNull);
    await expectLater(find.byType(Scaffold), matchesGoldenFile('goldens/plugin_controls_narrow_large.png'));
  });
}
